mapper.update:
UPDATE ${tableName}
SET status     = #{status},
    update_time=now()
WHERE primary_key = #{id}

mapper.select:
SELECT *
FROM ${tableName}
WHERE primary_key = #{primaryKeyValue}
  AND enterprise_code = #{enterpriseCode}

SELECT *
FROM ${tableName}
WHERE select_page_code = #{selectPageCode}
  AND department_code = #{departmentCode}
  AND enterprise_code = #{enterpriseCode}

SELECT *
FROM ${tableName} where primary_key in

    ${o}

and enterprise_code = #{enterpriseCode}

SELECT *
FROM ${tableName}
where config_id = #{configId}
  and department_code = #{departmentCode}
  and enterprise_code = #{enterpriseCode}
